text:
	# CM: engine tick suppressed on the five intercepted cards
	visible = "[And(AutomatedSystemsItem.IsEnabled, Not(Or5(AutomatedSystemsItem.IsName('expandbuildings'), AutomatedSystemsItem.IsName('expandrgo'), AutomatedSystemsItem.IsName('buildings'), AutomatedSystemsItem.IsName('closebuildings'), AutomatedSystemsItem.IsName('destroybuildings'))))]"
}
# CM: the five intercepted cards tick from this mod's own settings
icon = {
	size = { 100% 100% }
	using = checkbox_auto_texture
	frame = 2
	visible = "[Or5(And(AutomatedSystemsItem.IsName('expandbuildings'), GetScriptedGui('cm_is_auto_expand_buildings_feature_enabled').IsShown(GuiScope.SetRoot(GetPlayer.MakeScope).End)), And(AutomatedSystemsItem.IsName('expandrgo'), GetScriptedGui('cm_is_auto_expand_rgos_feature_enabled').IsShown(GuiScope.SetRoot(GetPlayer.MakeScope).End)), And(AutomatedSystemsItem.IsName('buildings'), GetScriptedGui('cm_ab_is_master_enabled').IsShown(GuiScope.SetRoot(GetPlayer.MakeScope).End)), And(AutomatedSystemsItem.IsName('closebuildings'), GetScriptedGui('cm_cu_close_open_is_enabled').IsShown(GuiScope.SetRoot(GetPlayer.MakeScope).End)), And(AutomatedSystemsItem.IsName('destroybuildings'), GetScriptedGui('cm_cu_destroy_is_enabled').IsShown(GuiScope.SetRoot(GetPlayer.MakeScope).End)))]"

				# CM: two-way link between this slider and the Gold Reserve setting

				# Arms a push on every card creation: the settings value wins the open.
				widget = {
					size = { 0 0 }
					visible_at_creation = no
					visible = "[GetPlayer.Exists]"
					state = {
						name = _show
						on_start = "[GetScriptedGui('cm_gold_reserve_reconcile').Execute(GuiScope.SetRoot(GetPlayer.MakeScope).End)]"
					}
				}

				# Pull: samples the slider into the reserve setting on a loop. A
				# visibility-gated transition goes sticky after a few changes.
				widget = {
					size = { 0 0 }
					state = {
						name = cm_gold_reserve_poll
						trigger_on_create = yes
						duration = 0.25
						on_finish = "[GetScriptedGui('cm_gold_reserve_changed').Execute(GuiScope.SetRoot(GetPlayer.MakeScope).AddScope('cm_gold_res', MakeScopeValue(AutomatedSystemsItem.GetGoldSliderScaled)).End)]"
						on_finish = "[PdxGuiWidget.TriggerAnimation('cm_gold_reserve_poll')]"
					}
				}

				# Samples the engine slider's scale, which appears in no file.
				widget = {
					size = { 0 0 }
					visible_at_creation = no
					visible = "[And(GreaterThan_CFixedPoint(AutomatedSystemsItem.GetGoldSlider, '(CFixedPoint)0'), Not(EqualTo_CFixedPoint(Divide_CFixedPoint(AutomatedSystemsItem.GetGoldSliderScaled, AutomatedSystemsItem.GetGoldSlider), GuiScope.AddScope('cm_country', GetPlayer.MakeScope).ScriptValue('cm_gold_reserve_max_value'))))]"
					state = {
						name = _show
						on_start = "[GetScriptedGui('cm_gold_reserve_max_changed').Execute(GuiScope.SetRoot(GetPlayer.MakeScope).AddScope('cm_gold_max', MakeScopeValue(Divide_CFixedPoint(AutomatedSystemsItem.GetGoldSliderScaled, AutomatedSystemsItem.GetGoldSlider))).End)]"
					}
				}

				# The equality branch clears a pending flag that has nothing to push.
				widget = {
					size = { 0 0 }
					visible_at_creation = no
					visible = "[And(GetPlayer.MakeScope.GetVariable('cm_gold_reserve_from_cmm').IsSet, Or(GreaterThan_CFixedPoint(GuiScope.AddScope('cm_country', GetPlayer.MakeScope).ScriptValue('cm_gold_reserve_max_value'), '(CFixedPoint)0'), EqualTo_CFixedPoint(AutomatedSystemsItem.GetGoldSliderScaled, GuiScope.AddScope('cm_country', GetPlayer.MakeScope).ScriptValue('cm_gold_reserve_value'))))]"
					state = {
						name = _show
						duration = 0.3
						on_finish = "[AutomatedSystemsItem.PostGoldSlider]"
						on_finish = "[GetScriptedGui('cm_gold_reserve_pushed').Execute(GuiScope.SetRoot(GetPlayer.MakeScope).End)]"
					}
				}
			}
		}
	}
}
